package com.bank.npe;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class HelpfulNpeTest {

    record Trade(String id, String symbol) {}

    @Test void helpfulMessageShowsWhichIsNull() {
        Trade trade = null;
        assertThatThrownBy(() -> trade.symbol())
            .isInstanceOf(NullPointerException.class)
            .hasMessageContaining("\"trade\" is null");
    }

    @Test void helpfulMessageForChainedCalls() {
        record Account(Trade trade) {}
        Account account = new Account(null);
        assertThatThrownBy(() -> account.trade().symbol())
            .isInstanceOf(NullPointerException.class)
            .hasMessageContaining("Trade.symbol()");
    }

    @Test void npeStillHappens_notPrevented() {
        // Helpful NPE doesn't PREVENT the crash — just better diagnostics
        String str = null;
        assertThatThrownBy(() -> str.length())
            .isInstanceOf(NullPointerException.class);
        // Prevention: Optional, null checks, @NonNull
    }
}
