package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class HelpfulNpeTest {

    record Holder(String email) {}
    record Account(Holder holder) {}

    @Test
    void npeMessageNamesTheNullReference() {
        Account acc = new Account(null);   // holder is null

        assertThatThrownBy(() -> acc.holder().email())
            .isInstanceOf(NullPointerException.class)
            .hasMessageContaining("holder()");   // message pinpoints the null part
    }
}
